import { describe, expect, it } from "vitest";
import { detectCodingPlanProvider } from "@/config/codingPlanProviders";
import { COPILOT_REASONING_EFFORTS } from "@/config/copilotConfig";
import {
  HERMES_PROVIDER_SOURCE_CUSTOM_LIST,
  HERMES_PROVIDER_SOURCE_DICT,
  HERMES_PROVIDER_SOURCE_FIELD,
} from "@/config/hermesProviderPresets";
import { CODEX_RESERVED_MODEL_PROVIDER_IDS } from "@/utils/providerConfigUtils";
import backend from "./backendConstants.json";

// backendConstants.json is generated by the backend test
// backend_constants_match_shared_fixture (src-tauri/src/frontend_parity_tests.rs).
// Each frontend copy below must match it.
describe("frontend copies of backend constants", () => {
  it("offers the Copilot reasoning efforts the backend accepts", () => {
    expect([...COPILOT_REASONING_EFFORTS]).toEqual(
      backend.copilotReasoningEfforts,
    );
  });

  it("reserves the same Codex model provider IDs", () => {
    expect([...CODEX_RESERVED_MODEL_PROVIDER_IDS]).toEqual(
      backend.codexReservedModelProviderIds,
    );
  });

  it("reads the Hermes provider source marker the backend writes", () => {
    expect({
      field: HERMES_PROVIDER_SOURCE_FIELD,
      customList: HERMES_PROVIDER_SOURCE_CUSTOM_LIST,
      dict: HERMES_PROVIDER_SOURCE_DICT,
    }).toEqual(backend.hermesProviderSource);
  });

  it.each(Object.entries(backend.codingPlanProviderByUrl))(
    "detects the same coding plan for %s",
    (url, id) => {
      expect(detectCodingPlanProvider(url)).toBe(id);
    },
  );
});
